"use client";

import React, { useEffect, useRef, useState } from "react";

// ─── NeonBlade UI — GlitchText Stub ──────────────────────────────────────────
// Replace this file with the real component generated by:
//   npx neonblade add glitch-text

export interface GlitchTextProps {
  text: string;
  /** HTML element to render as. Defaults to "span". */
  as?: "h1" | "h2" | "h3" | "h4" | "p" | "span" | "div";
  intensity?: "low" | "medium" | "high";
  speed?: "slow" | "medium" | "fast";
  className?: string;
}

const GLITCH_CHARS = "!<>-_\\/[]{}—=+*^?#∆ΩΣΨΓΔ";
const randomChar = () => GLITCH_CHARS[Math.floor(Math.random() * GLITCH_CHARS.length)];

export function GlitchText({
  text,
  as: Tag = "span",
  intensity = "medium",
  speed = "medium",
  className = "",
}: GlitchTextProps) {
  const [displayed, setDisplayed] = useState(text);
  const [isGlitching, setIsGlitching] = useState(false);
  const frameRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const intervalMs   = speed     === "fast"   ? 60  : speed     === "slow"   ? 200 : 110;
  const glitchChance = intensity === "high"   ? 0.35 : intensity === "low"   ? 0.08 : 0.18;
  const glitchDur    = intensity === "high"   ? 380  : intensity === "low"   ? 120  : 220;

  useEffect(() => {
    const triggerGlitch = () => {
      setIsGlitching(true);
      const end = Date.now() + glitchDur;
      const tick = () => {
        if (Date.now() > end) { setDisplayed(text); setIsGlitching(false); return; }
        setDisplayed(
          text.split("").map((ch) =>
            ch !== " " && Math.random() < glitchChance ? randomChar() : ch
          ).join("")
        );
        frameRef.current = setTimeout(tick, intervalMs);
      };
      tick();
    };

    const scheduleNext = () => {
      const delay = 2500 + Math.random() * 2500;
      frameRef.current = setTimeout(() => { triggerGlitch(); scheduleNext(); }, delay);
    };
    scheduleNext();
    return () => { if (frameRef.current) clearTimeout(frameRef.current); };
  }, [text, glitchChance, glitchDur, intervalMs]);

  const inner = (
    <>
      <span className="relative z-10">{displayed}</span>
      {isGlitching && (
        <>
          <span
            aria-hidden
            className="absolute inset-0 z-0 text-red-500/60"
            style={{ transform: "translate(-3px, 1px)", clipPath: "inset(30% 0 40% 0)" }}
          >{displayed}</span>
          <span
            aria-hidden
            className="absolute inset-0 z-0 text-cyan-400/60"
            style={{ transform: "translate(3px, -1px)", clipPath: "inset(55% 0 10% 0)" }}
          >{displayed}</span>
        </>
      )}
    </>
  );

  const props = {
    className: `relative select-none ${className}`,
    "aria-label": text,
    "data-glitching": isGlitching,
  };

  switch (Tag) {
    case "h1":  return <h1  {...props}>{inner}</h1>;
    case "h2":  return <h2  {...props}>{inner}</h2>;
    case "h3":  return <h3  {...props}>{inner}</h3>;
    case "h4":  return <h4  {...props}>{inner}</h4>;
    case "p":   return <p   {...props}>{inner}</p>;
    case "div": return <div {...props}>{inner}</div>;
    default:    return <span {...props}>{inner}</span>;
  }
}
